// ─────────────────────────────────────────────────────────────────────────────
// Console internals. Presentation timings and ranking weights ONLY — every
// number that touches the simulation comes from /src/config (see GEN in
// game/world/generate.ts for the same distinction on the worldgen side).
// ─────────────────────────────────────────────────────────────────────────────

const CONSOLE = {
  /** How often the reticle re-acquires the hex beneath it. */
  acquireMs: 150,
  /** Acquisition lockout while a programmatic camera flight is in the air. */
  flightMs: 720,
  /** Sites a single scan offers. */
  offerCount: 8,
  /** Minimum separation between offered sites, in hexes. */
  offerSpread: 3,
  /** Candidate pool drawn before scoring. */
  poolSize: 64,
  /** How long the arming overlay is guaranteed to stay on screen. */
  armMs: 620,
} as const;

/**
 * Site-ranking weights. These order a list of suggestions in the UI; they never
 * enter the simulation, so they deliberately do NOT live in /src/config.
 */
const WEIGHT = {
  gasField: 60,
  gasWithinReach: 18,
  gasReachHexes: 2,
  openNeighbour: 6,
  roomThreshold: 4,
  exposedSector: -140,
  closingSector: -1000,
  rivalAdjacent: -90,
  rivalNear: -45,
  rivalNearHexes: 2,
  rivalClearHexes: 5,
  rivalClear: 24,
  bannerBase: 60,
  bannerFalloff: 8,
  bannerNearHexes: 3,
  bannerNear: 18,
  /** Gas is worth this many minerals when ranking raw output. */
  gasToMinerals: 8,
} as const;

