type ScanMode = 'optimal' | 'banner';

// ─────────────────────────────────────────────────────────────────────────────
// Legality — mirrors IBackend.deploy exactly (GDD §3.1). Derived here from the
// exported world primitives rather than duplicated: `sectorOf` + `isHexOpen`
// decide playability, `areHostile` / `hostileArmyOnHex` decide contest.
// ─────────────────────────────────────────────────────────────────────────────

type Blocker = 'ok' | 'unsurveyed' | 'sealed' | 'closing' | 'rival' | 'occupied' | 'contested';

interface Legality {
  ok: boolean;
  code: Blocker;
  /** Short uppercase verdict for the strip. */
  verdict: string;
  /** Sentence-case explanation. */
  reason: string;
}

const CLEAR: Legality = {
  ok: true,
  code: 'ok',
  verdict: 'CLEAR FOR DROP',
  reason: 'Uncontested active ground. The corridor is open.',
};

function legality(state: GameState, hexId: HexId): Legality {
  const hex = state.world.hexes[hexId];
  if (!hex) {
    return {
      ok: false,
      code: 'unsurveyed',
      verdict: 'NO SURVEY',
      reason: 'Nothing has been charted at that grid reference.',
    };
  }
  const sector = sectorOf(state.world, hexId);
  if (!sector || !isHexOpen(state.world, hexId)) {
    return {
      ok: false,
      code: 'sealed',
      verdict: 'SECTOR SEALED',
      reason: 'That sector is locked. There is no drop corridor into it.',
    };
  }
  if (sector.state !== 'active') {
    return {
      ok: false,
      code: 'closing',
      verdict: 'SECTOR SHUTTING DOWN',
      reason:
        'That sector goes dark at the next rotation. Emplacements are levelled, ownership is wiped ' +
        'and every column inside is force-retreated. Nothing lands there.',
    };
  }
  if (hex.ownerId && areHostile(state, hex.ownerId, state.meId)) {
    const holder = state.players[hex.ownerId];
    return {
      ok: false,
      code: 'rival',
      verdict: 'HELD BY A RIVAL',
      reason: `${holder?.name ?? 'A rival commander'} controls this hex. Take it the hard way, later.`,
    };
  }
  const intruder = hostileArmyOnHex(state, hexId, state.meId);
  if (intruder) {
    return {
      ok: false,
      code: 'occupied',
      verdict: 'HOSTILE COLUMN ON SITE',
      reason: `${intruder.name} is standing on that hex. A pod would come down on top of it.`,
    };
  }
  if (hex.capture && hex.capture.playerId !== state.meId) {
    return {
      ok: false,
      code: 'contested',
      verdict: 'CAPTURE RUNNING',
      reason: 'Someone else is already flipping this hex. Pick ground nobody is standing on.',
    };
  }
  return CLEAR;
}

// ─────────────────────────────────────────────────────────────────────────────
// Sector shutdown exposure (GDD §3.2)
// ─────────────────────────────────────────────────────────────────────────────

type Risk = 'stable' | 'exposed' | 'closing' | 'opening';

interface RiskReport {
  risk: Risk;
  label: string;
  /** Confirmed or projected shutdown instant; undefined when nothing is due. */
  at?: number;
  confirmed: boolean;
  note: string;
}

/**
 * Which active sector is first in line to shut down. Mirrors the ordering
 * `world/rotation.pickClosingSector` uses — longest open first, id as the
 * tiebreak — so the console never promises a sector the server will take away.
 */
function firstInLine(state: GameState): Sector | undefined {
  const active = Object.values(state.world.sectors).filter((s) => s.state === 'active');
  active.sort((a, b) => {
    const oa = a.opensAt ?? 0;
    const ob = b.opensAt ?? 0;
    if (oa !== ob) return oa - ob;
    return a.id < b.id ? -1 : 1;
  });
  return active[0];
}

function assessRisk(state: GameState, sector: Sector, exposedId: string | undefined): RiskReport {
  if (sector.state === 'closing') {
    return {
      risk: 'closing',
      label: 'SHUTDOWN CONFIRMED',
      at: sector.closesAt ?? state.season.nextRotationAt,
      confirmed: true,
      note: 'This sector is already on the board to go dark. Everything in it is written off.',
    };
  }
  if (sector.state === 'unlocking') {
    return {
      risk: 'opening',
      label: 'UNSEALING',
      at: sector.opensAt ?? state.season.nextRotationAt,
      confirmed: true,
      note:
        'Announced but not yet open. Nothing lands here until the rotation runs — and everyone else ' +
        'is reading the same clock.',
    };
  }
  if (sector.state !== 'active') {
    return {
      risk: 'closing',
      label: 'SEALED',
      confirmed: true,
      note: 'Not yet unsealed. No corridor, no drop.',
    };
  }
  if (exposedId !== undefined && exposedId === sector.id) {
    // A sector already in `closing` takes the imminent slot, so this one is due
    // one full rotation later.
    const pending = Object.values(state.world.sectors).some((s) => s.state === 'closing');
    return {
      risk: 'exposed',
      label: 'FIRST IN LINE',
      at: state.season.nextRotationAt + (pending ? SEASON.rotationMs : 0),
      confirmed: false,
      note:
        'This sector has been open longest, so it is next on the block. Projection, not an order — ' +
        'but do not build here expecting to keep it.',
    };
  }
  return {
    risk: 'stable',
    label: 'NO SHUTDOWN ON THE BOARD',
    confirmed: false,
    note: 'Nothing scheduled against this sector. As safe as this world gets.',
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Site survey
// ─────────────────────────────────────────────────────────────────────────────

interface Site {
  hexId: HexId;
  hex: Hex;
  sector: Sector;
  legal: Legality;
  out: Cost;
  risk: RiskReport;
  /** Neutral, playable, unoccupied neighbours — room to expand into. */
  room: number;
  /** Distance to the nearest gas field, Infinity when none is in range. */
  gasDist: number;
  /** Distance to the nearest rival holding or column. */
  rivalDist: number;
  /** Distance to the nearest hex or column flying your own banner. */
  bannerDist: number;
  score: number;
  reasons: string[];
}

interface Field {
  /** Rival-held hexes and hostile columns. */
  threats: HexId[];
  /** Friendly holdings and columns. */
  friends: HexId[];
  gas: HexId[];
  exposedId: string | undefined;
}

function surveyField(state: GameState): Field {
  const threats: HexId[] = [];
  const friends: HexId[] = [];
  const gas: HexId[] = [];

  for (const hex of Object.values(state.world.hexes)) {
    if (hex.gas && isHexOpen(state.world, hex.id)) gas.push(hex.id);
    if (!hex.ownerId) continue;
    if (areHostile(state, hex.ownerId, state.meId)) threats.push(hex.id);
    else friends.push(hex.id);
  }
  for (const army of Object.values(state.armies)) {
    if (army.units.length === 0) continue;
    if (areHostile(state, army.ownerId, state.meId)) threats.push(army.hexId);
    else friends.push(army.hexId);
  }

  return { threats, friends, gas, exposedId: firstInLine(state)?.id };
}

function nearest(from: HexId, list: HexId[]): number {
  let best = Infinity;
  for (const id of list) {
    const d = hexDistanceId(from, id);
    if (d < best) best = d;
    if (best === 0) break;
  }
  return best;
}

function surveySite(state: GameState, hexId: HexId, field: Field, mode: ScanMode): Site | null {
  const hex = state.world.hexes[hexId];
  const sector = sectorOf(state.world, hexId);
  if (!hex || !sector) return null;

  const legal = legality(state, hexId);
  const out = hexYield(state, hex);
  const risk = assessRisk(state, sector, field.exposedId);

  let room = 0;
  for (const nb of neighborIds(hexId)) {
    const other = state.world.hexes[nb];
    if (!other) continue;
    if (!isHexOpen(state.world, nb)) continue;
    if (other.ownerId !== undefined) continue;
    if (hostileArmyOnHex(state, nb, state.meId)) continue;
    room++;
  }

  const gasDist = hex.gas ? 0 : nearest(hexId, field.gas);
  const rivalDist = nearest(hexId, field.threats);
  const bannerDist = nearest(hexId, field.friends);

  let score = out.m + out.g * WEIGHT.gasToMinerals;
  if (hex.gas) score += WEIGHT.gasField;
  score += room * WEIGHT.openNeighbour;
  if (gasDist > 0 && gasDist <= WEIGHT.gasReachHexes) score += WEIGHT.gasWithinReach;
  if (risk.risk === 'exposed') score += WEIGHT.exposedSector;
  if (risk.risk === 'closing') score += WEIGHT.closingSector;
  if (rivalDist <= 1) score += WEIGHT.rivalAdjacent;
  else if (rivalDist <= WEIGHT.rivalNearHexes) score += WEIGHT.rivalNear;
  else if (rivalDist >= WEIGHT.rivalClearHexes) score += WEIGHT.rivalClear;
  if (mode === 'banner' && Number.isFinite(bannerDist)) {
    score += Math.max(0, WEIGHT.bannerBase - bannerDist * WEIGHT.bannerFalloff);
  } else if (bannerDist <= WEIGHT.bannerNearHexes) {
    score += WEIGHT.bannerNear;
  }

  // ── the honest part: say why ────────────────────────────────────────────────
  const reasons: string[] = [];
  if (hex.gas) reasons.push('GAS FIELD — the only source of Gas on this world');
  if (risk.risk === 'stable') reasons.push('SECTOR STABLE — no shutdown on the board');
  if (risk.risk === 'exposed') reasons.push('SECTOR FIRST IN LINE — projected to go dark next rotation');
  if (risk.risk === 'closing') reasons.push('SECTOR SHUTTING DOWN — this ground is already forfeit');
  if (!hex.gas && gasDist > 0 && gasDist <= WEIGHT.gasReachHexes) {
    reasons.push(`GAS ${gasDist} ${gasDist === 1 ? 'HEX' : 'HEXES'} OUT — inside a first-week march`);
  }
  if (room >= WEIGHT.roomThreshold) reasons.push(`${room} NEUTRAL HEXES ADJACENT — room to expand`);
  if (rivalDist <= WEIGHT.rivalNearHexes) {
    reasons.push(`RIVAL FORCES ${rivalDist} OUT — contested from the first hour`);
  } else if (rivalDist >= WEIGHT.rivalClearHexes && Number.isFinite(rivalDist)) {
    reasons.push(`NEAREST RIVAL ${rivalDist} HEXES OUT — quiet ground`);
  } else if (!Number.isFinite(rivalDist)) {
    reasons.push('NO RIVAL PRESENCE SURVEYED IN THIS THEATRE');
  }
  if (Number.isFinite(bannerDist) && bannerDist <= WEIGHT.bannerNearHexes) {
    reasons.push(`YOUR BANNER HOLDS GROUND ${bannerDist} OUT — mutual support`);
  }
  reasons.push(`${fmtNum(out.m)} MINERALS PER ${fmtDuration(ECONOMY.tickMs)} TICK`);

  return { hexId, hex, sector, legal, out, risk, room, gasDist, rivalDist, bannerDist, score, reasons };
}

/**
 * Rank legal drop sites. The pool comes from `randomDeployableHexes` — the same
 * deterministic, well-spread offer list the world module already exposes — and
 * is only widened to a full sweep when that pool comes up short.
 */
function scanSites(state: GameState, mode: ScanMode): Site[] {
  const field = surveyField(state);

  const seen = new Set<HexId>();
  const pool: HexId[] = [];
  for (const id of randomDeployableHexes(state, CONSOLE.poolSize)) {
    if (seen.has(id)) continue;
    seen.add(id);
    if (legality(state, id).ok) pool.push(id);
  }
  if (pool.length < CONSOLE.offerCount) {
    for (const id of Object.keys(state.world.hexes)) {
      if (seen.has(id)) continue;
      seen.add(id);
      if (legality(state, id).ok) pool.push(id);
    }
  }

  const rated: Site[] = [];
  for (const id of pool) {
    const site = surveySite(state, id, field, mode);
    if (site && site.legal.ok) rated.push(site);
  }
  rated.sort((a, b) => b.score - a.score || (a.hexId < b.hexId ? -1 : 1));

  // Spread the offer so the console never suggests eight hexes in one pocket.
  const picked: Site[] = [];
  for (const site of rated) {
    if (picked.length >= CONSOLE.offerCount) break;
    let far = true;
    for (const other of picked) {
      if (hexDistanceId(site.hexId, other.hexId) < CONSOLE.offerSpread) {
        far = false;
        break;
      }
    }
    if (far) picked.push(site);
  }
  for (const site of rated) {
    if (picked.length >= CONSOLE.offerCount) break;
    if (!picked.includes(site)) picked.push(site);
  }
  return picked;
}

