export function createStagingScreen(backend: IBackend): Screen {
  const root = el('div', { class: 'screen staging' });
  const clock = new SimClock();
  const disposer = new Disposer();

  // ── scene ─────────────────────────────────────────────────────────────────
  const sceneHost = el('div', { class: 'stg__scene' });
  root.appendChild(sceneHost);
  root.appendChild(
    el(
      'div',
      { class: 'stg__atmos', aria: { hidden: 'true' } },
      el('i', { class: 'stg__atmos-horizon' }),
      el('i', { class: 'stg__atmos-vig' }),
      el('i', { class: 'stg__atmos-scan' }),
      el('i', { class: 'stg__atmos-chroma' }),
      el('i', { class: 'stg__atmos-drift' }),
    ),
  );

  let scene: MapScene | null = null;
  let mounted = false;

  // ── reticle ───────────────────────────────────────────────────────────────
  const aimTagId = el('span', { class: 'stg__aim-id mono', text: '——' });
  const aimTagState = el('span', { class: 'stg__aim-state', text: 'ACQUIRING' });
  const aim = el(
    'div',
    { class: 'stg__aim', aria: { hidden: 'true' } },
    el('div', { class: 'stg__reticle' }, svgEl(RETICLE)),
    el('div', { class: 'stg__aim-tag' }, aimTagId, aimTagState),
  );
  root.appendChild(aim);

  // ── telemetry rails ───────────────────────────────────────────────────────
  const siteRail = el('div', { class: 'stg__rail stg__rail--sites' });
  const sectorRail = el('div', { class: 'stg__rail stg__rail--sectors' });
  root.appendChild(el('div', { class: 'stg__rails' }, siteRail, sectorRail));

  // ── top chrome ────────────────────────────────────────────────────────────
  const briefBtn = iconButton(ICONS.info, {
    variant: 'bare',
    small: true,
    label: 'drop briefing',
    class: 'stg__brief-btn',
    onClick: () => openBrief(true),
  });

  const headline = el(
    'div',
    { class: 'stg__head' },
    el(
      'div',
      { class: 'stg__head-mark' },
      svgEl(POD_GLYPH, 'stg__head-glyph'),
      el(
        'div',
        { class: 'grow' },
        el('div', { class: 'stg__head-title display', text: 'ORBITAL STAGING' }),
        el('div', { class: 'stg__head-sub mono', text: 'DROP POD CONTROL · NO GROUND HELD' }),
      ),
      briefBtn,
    ),
  );

  const rotSlot = el('div', { class: 'stg__rot' });
  const bannerSlot = el('div', { class: 'stg__banner' });
  const top = el('div', { class: 'stg__top' }, headline, rotSlot, bannerSlot);
  root.appendChild(top);

  // ── console ───────────────────────────────────────────────────────────────
  const cardSlot = el('div', { class: 'stg__card' });
  const modeSlot = el('div', { class: 'stg__mode' });

  const scanBtn = button('SCAN FOR SITES', {
    variant: 'ghost',
    icon: ICONS.target,
    class: 'stg__scan grow',
    onClick: () => runScan(true),
  });
  const prevBtn = iconButton(ICONS.chevronLeft, {
    small: true,
    label: 'previous site',
    class: 'stg__cyc',
    onClick: () => cycle(-1),
  });
  const nextBtn = iconButton(ICONS.chevronRight, {
    small: true,
    label: 'next site',
    class: 'stg__cyc',
    onClick: () => cycle(1),
  });
  const cycleCount = el('span', { class: 'stg__count mono', text: '—' });
  const scanRow = el(
    'div',
    { class: 'stg__scanrow' },
    scanBtn,
    el('div', { class: 'stg__cycler' }, prevBtn, cycleCount, nextBtn),
  );

  const manifest = el('div', { class: 'stg__manifest' });
  const launchBtn = button('LAUNCH DROP POD', {
    variant: 'primary',
    wide: true,
    class: 'stg__launch-btn',
    onClick: () => void beginLaunch(),
  });

  const consoleSlot = el(
    'div',
    { class: 'stg__console' },
    el('i', { class: 'stg__console-rim', aria: { hidden: 'true' } }),
    cardSlot,
    modeSlot,
    manifest,
    scanRow,
    launchBtn,
  );
  root.appendChild(consoleSlot);

  // ── overlays ──────────────────────────────────────────────────────────────
  const briefLayer = el('div', { class: 'stg__ftue', aria: { hidden: 'true' } });
  const guildLayer = el('div', { class: 'stg__sheet', aria: { hidden: 'true' } });
  const armLayer = el('div', { class: 'stg__arming', aria: { hidden: 'true' } });
  root.appendChild(briefLayer);
  root.appendChild(guildLayer);
  root.appendChild(armLayer);

  // ── live state ────────────────────────────────────────────────────────────
  let targetHexId: HexId | undefined;
  let offers: HexId[] = [];
  let offerIdx = -1;
  let scanMode: ScanMode = 'optimal';
  /** Dossier drawer state — the crown line always stays, the rest folds away. */
  let cardOpen = false;
  let launching = false;
  let acquireAcc = 0;
  let flightUntil = 0;
  let modeTabs: TabsController | null = null;
  let guildView: GuildTabView | null = null;
  let guildOpen = false;

  let cardSig = '';
  let rotSig = '';
  let bannerSig = '';
  let siteRailSig = '';
  let sectorRailSig = '';
  let manifestBuilt = false;

  const cardTimers: CountdownController[] = [];
  const rotTimers: CountdownController[] = [];

  const stopAll = (list: CountdownController[]): void => {
    for (const t of list.splice(0)) t.stop();
  };

  const stateOrNull = (): GameState | null => game.get();

  // ── scene wiring (mirrors screens/map.ts lifecycle discipline) ─────────────
  function buildScene(): void {
    if (scene) return;
    const created = new MapScene(sceneHost);
    created.onHexTap((hexId) => {
      haptic(9);
      selectSite(hexId, { focus: true, pulse: true });
    });
    created.onHexLongPress((hexId) => {
      haptic([10, 26, 10]);
      selectSite(hexId, { focus: true, pulse: true });
    });
    created.onEmptyTap(() => {
      /* the reticle is the selection; a miss changes nothing */
    });
    scene = created;
  }

  function teardownScene(): void {
    if (!scene) return;
    scene.dispose();
    scene = null;
  }

  // ── selection ─────────────────────────────────────────────────────────────
  function selectSite(hexId: HexId, opts: { focus?: boolean; pulse?: boolean } = {}): void {
    targetHexId = hexId;
    const idx = offers.indexOf(hexId);
    offerIdx = idx;
    if (view.get().selectedHexId !== hexId) view.patch({ selectedHexId: hexId });
    if (opts.focus) {
      focusHex(hexId);
      flightUntil = performance.now() + CONSOLE.flightMs;
    }
    if (opts.pulse) scene?.pulse(hexId, PALETTE.cyan);
    const state = stateOrNull();
    if (state) {
      renderCard(state);
      renderSiteRail(state);
    }
  }

  function cycle(step: number): void {
    if (offers.length === 0) {
      runScan(true);
      return;
    }
    // A reticle-acquired hex is not in the offer list; stepping off it enters
    // the list at the end the player was heading toward.
    const next =
      offerIdx >= 0
        ? (offerIdx + step + offers.length) % offers.length
        : step > 0
          ? 0
          : offers.length - 1;
    haptic(9);
    selectSite(offers[next], { focus: true, pulse: true });
  }

  function runScan(announce: boolean): void {
    const state = stateOrNull();
    if (!state) return;
    haptic([8, 22, 8]);
    root.classList.remove('is-scanning');
    void root.offsetWidth;
    root.classList.add('is-scanning');
    window.setTimeout(() => root.classList.remove('is-scanning'), 900);

    const sites = scanSites(state, scanMode);
    offers = sites.map((s) => s.hexId);
    siteRailSig = '';
    renderSiteRail(state);

    if (offers.length === 0) {
      offerIdx = -1;
      cardSig = '';
      renderCard(state);
      if (announce) {
        toast({
          title: 'NO LANDING ZONE',
          body: 'Every active hex is held, occupied or contested. Hold for the next rotation.',
          kind: 'bad',
        });
      }
      return;
    }

    if (announce) {
      const best = sites[0];
      toast({
        title: `${offers.length} SITE${offers.length === 1 ? '' : 'S'} OFFERED`,
        body: `${best.hexId} · ${TERRAIN_META[best.hex.terrain].label} · ${best.sector.designation}`,
        kind: 'intel',
      });
    }
    selectSite(offers[0], { focus: true, pulse: true });
  }

  // ── rotation strip (GDD §3.2) ─────────────────────────────────────────────
  function renderRotation(state: GameState): void {
    const rot = upcomingRotation(state, clock.now());
    const sig = `${rot.opening?.id ?? '-'}|${rot.closing?.id ?? '-'}|${rot.at}`;
    if (sig === rotSig) return;
    rotSig = sig;
    stopAll(rotTimers);
    clear(rotSlot);

    const slab = (kicker: string, name: string, at: number, mod: string, hexId?: HexId): HTMLElement => {
      const node = el('div', { class: `stg__rot-slab stg__rot-slab--${mod}` });
      node.appendChild(el('span', { class: 'stg__rot-kicker', text: kicker }));
      node.appendChild(el('span', { class: 'stg__rot-name display truncate', text: name }));
      const cd = countdown(at, { getNow: () => clock.now(), compact: true, doneText: 'NOW' });
      rotTimers.push(cd);
      node.appendChild(cd.el);
      if (hexId) {
        node.addEventListener('click', () => {
          focusHex(hexId);
          flightUntil = performance.now() + CONSOLE.flightMs;
          haptic(9);
        });
        node.classList.add('is-tappable');
      }
      return node;
    };

    if (rot.opening || rot.closing) {
      const pair = el('div', { class: 'stg__rot-pair' });
      pair.appendChild(
        slab(
          'UNSEALING',
          rot.opening?.designation ?? 'UNDISCLOSED',
          rot.at,
          'open',
          rot.opening ? `${rot.opening.center.q},${rot.opening.center.r}` : undefined,
        ),
      );
      pair.appendChild(
        slab(
          'SHUTDOWN',
          rot.closing?.designation ?? 'UNDISCLOSED',
          rot.at,
          'close',
          rot.closing ? `${rot.closing.center.q},${rot.closing.center.r}` : undefined,
        ),
      );
      rotSlot.appendChild(pair);
    } else {
      const revealAt = rot.at - SEASON.announceMs;
      const cd = countdown(revealAt, {
        getNow: () => clock.now(),
        prefix: 'REVEAL IN',
        doneText: 'DECRYPTING',
      });
      rotTimers.push(cd);
      rotSlot.appendChild(
        el(
          'div',
          { class: 'stg__rot-sealed hatch--cold' },
          el('span', { class: 'stg__rot-kicker', text: 'ROTATION ORDER SEALED' }),
          cd.el,
        ),
      );
    }
  }

  // ── guild strip ───────────────────────────────────────────────────────────
  function renderBanner(state: GameState): void {
    const me = state.players[state.meId];
    const guild = me?.guildId ? state.guilds[me.guildId] : undefined;
    const sig = guild
      ? `g:${guild.id}:${guild.memberIds.length}:${guild.color}:${guild.emblem}`
      : `none:${Object.keys(state.guilds).length}`;
    if (sig === bannerSig) return;
    bannerSig = sig;
    clear(bannerSlot);

    if (!guild) {
      bannerSlot.classList.add('stg__banner--none');
      bannerSlot.appendChild(
        el(
          'div',
          { class: 'stg__banner-inner' },
          el('span', { class: 'stg__banner-flag', text: '◇', aria: { hidden: 'true' } }),
          el(
            'div',
            { class: 'grow' },
            el('div', { class: 'stg__banner-title display', text: 'NO BANNER ON FILE' }),
            el('div', {
              class: 'stg__banner-note',
              text: 'Chat, intel, shipments and diplomacy all run through a charter. Drop alone and you fight alone.',
            }),
          ),
          button('ENLIST', { variant: 'ghost', small: true, onClick: () => openGuild() }),
        ),
      );
      return;
    }

    bannerSlot.classList.remove('stg__banner--none');
    const online = guild.memberIds.reduce((n, id) => n + (state.players[id]?.online ? 1 : 0), 0);
    const sigil = el('div', { class: 'stg__banner-sigil' });
    sigil.appendChild(guildSigil(guild, 30));
    bannerSlot.appendChild(
      el(
        'div',
        { class: 'stg__banner-inner', style: `--band:${cssHex(guild.color)}` },
        sigil,
        el(
          'div',
          { class: 'grow' },
          el(
            'div',
            { class: 'row', style: 'gap:6px' },
            el('span', { class: 'stg__banner-title display truncate grow', text: guild.name }),
            el('span', { class: 'ghead__tag', text: guild.tag }),
          ),
          el('div', {
            class: 'stg__banner-note mono',
            text: `${guild.memberIds.length} COMMANDERS · ${online} ON NET`,
          }),
        ),
      ),
    );
  }

  // ── site rail ─────────────────────────────────────────────────────────────
  function renderSiteRail(state: GameState): void {
    const sig = `${offers.join(',')}|${targetHexId ?? '-'}`;
    if (sig === siteRailSig) return;
    siteRailSig = sig;
    clear(siteRail);

    siteRail.classList.toggle('is-empty', offers.length === 0);
    if (offers.length === 0) {
      siteRail.appendChild(el('span', { class: 'stg__rail-cap', text: 'SITES' }));
      siteRail.appendChild(el('span', { class: 'stg__rail-none', text: '—' }));
      return;
    }

    siteRail.appendChild(el('span', { class: 'stg__rail-cap', text: 'SITES' }));
    offers.forEach((hexId, i) => {
      const hex = state.world.hexes[hexId];
      const pip = el('button', {
        class: `stg__pip${hexId === targetHexId ? ' is-on' : ''}`,
        attrs: { type: 'button' },
        style: hex ? `--accent:${terrainAccent(hex.terrain)}` : undefined,
        aria: { label: `offered site ${i + 1}: ${hexId}` },
      });
      pip.appendChild(el('i', { class: 'stg__pip-tick', aria: { hidden: 'true' } }));
      pip.appendChild(el('span', { class: 'stg__pip-n mono', text: String(i + 1).padStart(2, '0') }));
      pip.appendChild(el('span', { class: 'stg__pip-id mono', text: hexId }));
      pip.addEventListener('click', () => selectSite(hexId, { focus: true, pulse: true }));
      siteRail.appendChild(pip);
    });
  }

  // ── sector rail ───────────────────────────────────────────────────────────
  function renderSectorRail(state: GameState): void {
    const sectors = Object.values(state.world.sectors)
      .filter((s) => s.state === 'active' || s.state === 'closing' || s.state === 'unlocking')
      .sort((a, b) => (a.id < b.id ? -1 : 1));
    const targetSector = targetHexId ? sectorOf(state.world, targetHexId)?.id : undefined;
    const exposedId = firstInLine(state)?.id;
    const sig = `${sectors.map((s) => `${s.id}:${s.state}`).join(',')}|${targetSector ?? '-'}|${exposedId ?? '-'}`;
    if (sig === sectorRailSig) return;
    sectorRailSig = sig;
    clear(sectorRail);

    sectorRail.appendChild(el('span', { class: 'stg__rail-cap', text: 'SECTORS' }));
    for (const sector of sectors) {
      const risk = assessRisk(state, sector, exposedId);
      const chip = el('button', {
        class: `stg__sec stg__sec--${risk.risk}${sector.id === targetSector ? ' is-on' : ''}`,
        attrs: { type: 'button' },
        aria: { label: `${sector.designation}, ${risk.label}` },
      });
      chip.appendChild(el('i', { class: 'stg__sec-dot', aria: { hidden: 'true' } }));
      chip.appendChild(el('span', { class: 'stg__sec-name', text: sector.name }));
      chip.addEventListener('click', () => {
        focusHex(`${sector.center.q},${sector.center.r}`);
        flightUntil = performance.now() + CONSOLE.flightMs;
        haptic(9);
      });
      sectorRail.appendChild(chip);
    }
  }

  // ── target dossier ────────────────────────────────────────────────────────
  function cell(k: string, v: string, tone?: string): HTMLElement {
    return el(
      'div',
      { class: 'stg__cell', style: tone ? `--accent:${tone}` : undefined },
      el('span', { class: 'stg__cell-k', text: k }),
      el('span', { class: 'stg__cell-v mono', text: v }),
    );
  }

  function cardSignature(state: GameState, site: Site | null): string {
    if (!site) return `none:${targetHexId ?? '-'}:${offers.length}`;
    return [
      site.hexId,
      site.hex.terrain,
      site.hex.ownerId ?? '-',
      site.hex.fortLevel,
      site.legal.code,
      site.risk.risk,
      site.risk.at ?? 0,
      site.out.m,
      site.out.g,
      site.room,
      site.rivalDist,
      site.bannerDist,
      site.gasDist,
      scanMode,
      state.meId,
    ].join('|');
  }

  function renderCard(state: GameState): void {
    const site = targetHexId
      ? surveySite(state, targetHexId, surveyField(state), scanMode)
      : null;

    const sig = cardSignature(state, site);
    if (sig === cardSig) return;
    cardSig = sig;
    stopAll(cardTimers);
    clear(cardSlot);

    // Cycler + launch availability track the dossier.
    cycleCount.textContent =
      offers.length === 0
        ? '—'
        : offerIdx >= 0
          ? `${offerIdx + 1}/${offers.length}`
          : `·/${offers.length}`;
    prevBtn.disabled = offers.length < 2;
    nextBtn.disabled = offers.length < 2;

    if (!site) {
      syncAimTag(null);
      launchBtn.disabled = true;
      cardSlot.classList.add('is-void');
      cardSlot.appendChild(
        emptyState(
          '◇',
          offers.length === 0
            ? 'no landing zone offered — every active hex is held, occupied or contested'
            : 'no site selected — scan, cycle, or aim the reticle at a hex',
        ),
      );
      const rot = upcomingRotation(state, clock.now());
      const cd = countdown(rot.at, {
        getNow: () => clock.now(),
        prefix: 'NEXT SECTOR ROTATION',
        doneText: 'ROTATING',
      });
      cardTimers.push(cd);
      cardSlot.appendChild(el('div', { class: 'stg__void-clock' }, cd.el));
      return;
    }

    cardSlot.classList.remove('is-void');
    launchBtn.disabled = !site.legal.ok || launching;
    launchBtn.classList.toggle('is-armed', site.legal.ok && !launching);

    const accent = terrainAccent(site.hex.terrain);
    const meta = TERRAIN_META[site.hex.terrain];
    cardSlot.style.setProperty('--accent', accent);

    const riskTone: 'ok' | 'gold' | 'bad' | 'violet' =
      site.risk.risk === 'stable'
        ? 'ok'
        : site.risk.risk === 'exposed'
          ? 'gold'
          : site.risk.risk === 'opening'
            ? 'violet'
            : 'bad';

    // ── crown: always visible, one line, the identity of the target ─────────
    const crown = el('button', {
      class: 'stg__crown',
      attrs: { type: 'button' },
      aria: { expanded: cardOpen, label: 'toggle target dossier' },
    });
    crown.appendChild(el('i', { class: 'stg__crown-tick', aria: { hidden: 'true' } }));
    crown.appendChild(el('span', { class: 'stg__crown-id mono', text: site.hexId }));
    crown.appendChild(el('span', { class: 'stg__crown-terr display truncate', text: meta.label }));
    crown.appendChild(el('span', { class: 'spacer' }));
    if (offerIdx >= 0) crown.appendChild(badge(`SITE ${offerIdx + 1}`, 'violet'));
    if (site.hex.gas) crown.appendChild(badge('GAS', 'ok'));
    if (site.hex.fortLevel > 0) crown.appendChild(badge(`L${site.hex.fortLevel}`, 'gold'));
    crown.appendChild(el('i', { class: 'stg__crown-chev', html: ICONS.chevronDown, aria: { hidden: 'true' } }));
    crown.addEventListener('click', () => {
      cardOpen = !cardOpen;
      cardSlot.classList.toggle('is-open', cardOpen);
      crown.setAttribute('aria-expanded', String(cardOpen));
      haptic(8);
    });
    cardSlot.appendChild(crown);

    // ── pulse line: the verdict and the shutdown clock, never hidden ────────
    const pulse = el('div', { class: `stg__pulse ${site.legal.ok ? 'is-ok' : 'is-bad'}` });
    pulse.appendChild(
      el('span', { class: 'stg__pulse-mark', text: site.legal.ok ? '✔' : '✖', aria: { hidden: 'true' } }),
    );
    pulse.appendChild(el('span', { class: 'stg__pulse-head display truncate', text: site.legal.verdict }));
    pulse.appendChild(el('span', { class: 'spacer' }));
    pulse.appendChild(
      el('span', { class: `stg__pulse-sec mono stg__risk--${site.risk.risk}`, text: site.sector.name }),
    );
    if (site.risk.at !== undefined) {
      const cd = countdown(site.risk.at, {
        getNow: () => clock.now(),
        compact: true,
        doneText: 'DARK',
      });
      cardTimers.push(cd);
      pulse.appendChild(cd.el);
    } else {
      pulse.appendChild(el('span', { class: 'stg__pulse-clear mono', text: 'NO SHUTDOWN' }));
    }
    cardSlot.appendChild(pulse);

    // ── detail drawer ──────────────────────────────────────────────────────
    const detail = el('div', { class: 'stg__detail' });

    // banner art
    const art = el('div', { class: 'stg__art', aria: { hidden: 'true' } });
    art.appendChild(svgEl(terrainArt(site.hex.terrain), 'stg__art-svg'));
    art.appendChild(el('i', { class: 'stg__art-scan' }));
    detail.appendChild(art);

    detail.appendChild(el('p', { class: 'stg__blurb', text: meta.blurb }));

    // readouts
    const grid = el('div', { class: 'stg__grid' });
    grid.appendChild(cell('MINERALS / TICK', fmtNum(site.out.m), 'var(--cyan)'));
    grid.appendChild(
      cell('GAS / TICK', site.out.g > 0 ? fmtNum(site.out.g) : '—', site.out.g > 0 ? 'var(--teal)' : 'var(--ink-4)'),
    );
    grid.appendChild(
      cell('OPEN NEIGHBOURS', `${site.room}/6`, site.room >= WEIGHT.roomThreshold ? 'var(--teal)' : 'var(--amber)'),
    );
    grid.appendChild(
      cell(
        'NEAREST RIVAL',
        Number.isFinite(site.rivalDist) ? `${site.rivalDist} HEX` : 'NONE',
        site.rivalDist <= WEIGHT.rivalNearHexes ? 'var(--crimson)' : 'var(--teal)',
      ),
    );
    detail.appendChild(grid);

    // sector + shutdown clock, spelled out
    const sec = el('div', { class: `stg__sector stg__sector--${site.risk.risk}` });
    sec.appendChild(
      el(
        'div',
        { class: 'stg__sector-head' },
        el('span', { class: 'stg__sector-name display truncate grow', text: site.sector.designation }),
        badge(site.risk.label, riskTone),
      ),
    );
    if (site.risk.at !== undefined) {
      const cd = countdown(site.risk.at, {
        getNow: () => clock.now(),
        prefix: site.risk.confirmed ? 'GOES DARK IN' : 'PROJECTED DARK IN',
        doneText: 'DARK',
      });
      cardTimers.push(cd);
      sec.appendChild(el('div', { class: 'stg__sector-clock' }, cd.el));
    }
    sec.appendChild(el('p', { class: 'stg__sector-note', text: site.risk.note }));
    detail.appendChild(sec);

    // why this site
    if (site.reasons.length > 0) {
      const why = el('div', { class: 'stg__why' });
      why.appendChild(el('span', { class: 'stg__why-cap', text: 'READ-OUT' }));
      for (const line of site.reasons.slice(0, 4)) {
        why.appendChild(el('div', { class: 'stg__why-line mono' }, el('i'), el('span', { text: line })));
      }
      detail.appendChild(why);
    }

    // holdings the console will not hide
    if (site.hex.ownerId !== undefined) {
      const holder = state.players[site.hex.ownerId];
      detail.appendChild(
        statRow('CURRENT HOLDER', holder?.name ?? 'UNKNOWN', {
          accent: site.legal.ok ? 'var(--teal)' : 'var(--crimson)',
        }),
      );
    }

    detail.appendChild(el('p', { class: 'stg__reason', text: site.legal.reason }));
    cardSlot.appendChild(detail);
    cardSlot.classList.toggle('is-open', cardOpen);

    syncAimTag(site);
  }

  function syncAimTag(site: Site | null): void {
    const locked = site !== null && site.legal.ok;
    const blocked = site !== null && !site.legal.ok;
    aimTagId.textContent = targetHexId ?? '——';
    aim.classList.toggle('is-locked', locked);
    aim.classList.toggle('is-blocked', blocked);
    aimTagState.textContent = locked ? 'LOCK' : blocked ? 'NO DROP' : 'ACQUIRING';
  }

  // ── drop manifest ─────────────────────────────────────────────────────────
  function buildManifest(): void {
    if (manifestBuilt) return;
    manifestBuilt = true;
    clear(manifest);
    manifest.appendChild(el('span', { class: 'stg__manifest-cap', text: 'MANIFEST' }));
    for (const [type, count] of Object.entries(ECONOMY.startingArmy) as [UnitType, number][]) {
      if (count <= 0) continue;
      const chip = el('span', {
        class: 'stg__unit',
        style: `--accent:${unitAccent(type)}`,
        aria: { label: `${count} ${UNITS[type].name}` },
      });
      chip.appendChild(svgEl(unitSilhouette(type), 'stg__unit-art'));
      chip.appendChild(el('b', { class: 'mono', text: `×${count}` }));
      manifest.appendChild(chip);
    }
    manifest.appendChild(el('span', { class: 'stg__manifest-sep', aria: { hidden: 'true' } }));
    manifest.appendChild(
      el('span', { class: 'stg__manifest-res mono', text: `${fmtNum(ECONOMY.startMinerals)} M` }),
    );
    manifest.appendChild(
      el('span', { class: 'stg__manifest-res mono is-gas', text: `${fmtNum(ECONOMY.startGas)} G` }),
    );
  }

  // ── scan-mode switch (guilded commanders only) ────────────────────────────
  function renderMode(state: GameState): void {
    const me = state.players[state.meId];
    const guilded = me?.guildId !== undefined;
    modeSlot.classList.toggle('hidden', !guilded);
    if (!guilded) {
      if (scanMode !== 'optimal') scanMode = 'optimal';
      return;
    }
    if (modeTabs) return;
    modeTabs = tabs(
      [
        { id: 'optimal', label: 'BEST GROUND' },
        { id: 'banner', label: 'NEAR BANNER' },
      ],
      (id: string) => {
        scanMode = id === 'banner' ? 'banner' : 'optimal';
        cardSig = '';
        runScan(true);
      },
      scanMode,
    );
    modeSlot.appendChild(modeTabs.el);
  }

  // ── first-contact briefing (GDD §13 step 8) ───────────────────────────────
  function alreadyBriefed(): boolean {
    try {
      return window.localStorage.getItem(BRIEF_KEY) === '1';
    } catch {
      return false;
    }
  }

  function markBriefed(): void {
    try {
      window.localStorage.setItem(BRIEF_KEY, '1');
    } catch {
      /* private mode — the briefing simply shows again */
    }
  }

  function briefSteps(): { idx: string; title: string; body: string }[] {
    const roster = (Object.entries(ECONOMY.startingArmy) as [UnitType, number][])
      .filter(([, n]) => n > 0)
      .map(([type, n]) => `${n}× ${UNITS[type].name}`)
      .join(', ');
    return [
      {
        idx: 'I',
        title: 'YOU ARE NOT ON THE MAP YET',
        body:
          'No hex, no column, no yield. You are a call-sign in orbit with a pod and one decision. ' +
          'Nothing down there knows you exist.',
      },
      {
        idx: 'II',
        title: 'PICK GROUND NOBODY HOLDS',
        body:
          'Any hex in an active sector that no rival controls, occupies or is already flipping. ' +
          'Aim the reticle, or let the console scan and rank sites for you.',
      },
      {
        idx: 'III',
        title: 'THE DROP IS ONE-WAY',
        body:
          `${roster} come down with you, plus ${fmtNum(ECONOMY.startMinerals)} minerals and ` +
          `${fmtNum(ECONOMY.startGas)} gas. Capture runs for ${fmtDuration(MAP.captureMs)}, then the hex pays ` +
          `every ${fmtDuration(ECONOMY.tickMs)} — and every rival on the net can see where you landed.`,
      },
      {
        idx: 'IV',
        title: 'THE GROUND EXPIRES',
        body:
          `Every ${fmtDuration(SEASON.rotationMs)} one sector goes dark and another unseals, announced ` +
          `${fmtDuration(SEASON.announceMs)} ahead. A sector that rotates out takes your works, your ownership ` +
          'and your position with it. Read the shutdown clock before you commit.',
      },
    ];
  }

  function closeBrief(): void {
    briefLayer.classList.remove('is-open');
    briefLayer.setAttribute('aria-hidden', 'true');
    window.setTimeout(() => {
      if (!briefLayer.classList.contains('is-open')) clear(briefLayer);
    }, 240);
  }

  function openBrief(manual: boolean): void {
    if (!manual && alreadyBriefed()) return;
    clear(briefLayer);

    const scrim = el('div', { class: 'stg__ftue-scrim' });
    scrim.addEventListener('pointerdown', (ev: PointerEvent) => {
      ev.preventDefault();
      markBriefed();
      closeBrief();
    });
    briefLayer.appendChild(scrim);

    const card = panel({
      title: 'DROP BRIEFING',
      subtitle: 'read once — the war does not repeat itself',
      accent: 'var(--gold)',
      class: 'stg__ftue-card',
      holo: true,
    });
    const body = card.querySelector('.panel__body');
    for (const step of briefSteps()) {
      body?.appendChild(
        el(
          'div',
          { class: 'stg__step' },
          el('span', { class: 'stg__step-idx display', text: step.idx }),
          el(
            'div',
            { class: 'grow' },
            el('div', { class: 'stg__step-title display', text: step.title }),
            el('p', { class: 'stg__step-body', text: step.body }),
          ),
        ),
      );
    }
    body?.appendChild(
      el(
        'div',
        { class: 'stg__ftue-acts' },
        button('SKIP', {
          variant: 'quiet',
          onClick: () => {
            markBriefed();
            closeBrief();
          },
        }),
        button('UNDERSTOOD', {
          variant: 'primary',
          icon: ICONS.check,
          onClick: () => {
            markBriefed();
            closeBrief();
            haptic(12);
          },
        }),
      ),
    );
    briefLayer.appendChild(card);

    briefLayer.classList.add('is-open');
    briefLayer.setAttribute('aria-hidden', 'false');
  }

  // ── guild overlay (reuses the real charter flow) ───────────────────────────
  function closeGuild(): void {
    guildOpen = false;
    guildLayer.classList.remove('is-open');
    guildLayer.setAttribute('aria-hidden', 'true');
  }

  function openGuild(): void {
    if (!guildView) {
      const created = createGuildCreate(backend);
      guildView = created;

      const scrim = el('div', { class: 'stg__sheet-scrim' });
      scrim.addEventListener('pointerdown', (ev: PointerEvent) => {
        ev.preventDefault();
        closeGuild();
      });

      const head = el(
        'div',
        { class: 'stg__sheet-head' },
        el(
          'div',
          { class: 'grow' },
          el('div', { class: 'stg__sheet-title display', text: 'BANNER REGISTRY' }),
          el('div', {
            class: 'stg__sheet-sub mono',
            text: 'FOUND A CHARTER OR ENLIST — YOU CAN STILL DROP ALONE',
          }),
        ),
        iconButton(ICONS.close, { variant: 'bare', label: 'close registry', onClick: () => closeGuild() }),
      );
      guildLayer.appendChild(scrim);
      guildLayer.appendChild(
        el(
          'div',
          { class: 'stg__sheet-panel' },
          head,
          el('div', { class: 'stg__sheet-body' }, created.el),
        ),
      );
    }
    guildOpen = true;
    guildLayer.classList.add('is-open');
    guildLayer.setAttribute('aria-hidden', 'false');
    haptic(10);
    const state = stateOrNull();
    if (state) guildView?.sync(state);
  }

  // ── the commit ────────────────────────────────────────────────────────────
  function playArming(hexId: HexId): void {
    clear(armLayer);
    armLayer.appendChild(
      el(
        'div',
        { class: 'stg__arming-inner' },
        el('div', { class: 'stg__arming-ring', aria: { hidden: 'true' } }),
        el('div', { class: 'stg__arming-title display', text: 'DROP POD ARMED' }),
        el(
          'div',
          { class: 'stg__arming-lines mono' },
          el('span', { class: 'stg__arming-line', text: 'PYROS ARMED' }),
          el('span', { class: 'stg__arming-line', text: 'TETHER RELEASED' }),
          el('span', { class: 'stg__arming-line', text: 'IGNITION' }),
        ),
        el('div', { class: 'stg__arming-hex mono', text: hexId }),
      ),
    );
    armLayer.classList.add('is-on');
    armLayer.setAttribute('aria-hidden', 'false');
    root.classList.add('is-launching');
  }

  function stopArming(): void {
    armLayer.classList.remove('is-on');
    armLayer.setAttribute('aria-hidden', 'true');
    root.classList.remove('is-launching');
    window.setTimeout(() => {
      if (!armLayer.classList.contains('is-on')) clear(armLayer);
    }, 260);
  }

  async function beginLaunch(): Promise<void> {
    if (launching) return;
    const state = stateOrNull();
    const hexId = targetHexId;
    if (!state || !hexId) {
      toast({ title: 'NO TARGET', body: 'Aim the reticle or run a scan first.', kind: 'warn' });
      return;
    }
    const site = surveySite(state, hexId, surveyField(state), scanMode);
    if (!site || !site.legal.ok) {
      toast({ title: 'DROP REFUSED', body: site?.legal.reason ?? 'That grid cannot take a pod.', kind: 'bad' });
      haptic([18, 40, 18]);
      return;
    }

    const shutdown =
      site.risk.at !== undefined
        ? ` The sector is ${site.risk.confirmed ? 'confirmed' : 'projected'} to go dark in ${fmtDuration(
            Math.max(0, site.risk.at - clock.now()),
          )}.`
        : '';

    const agreed = await confirmModal({
      title: 'COMMIT THE DROP',
      body:
        `Pod comes down on ${hexId} — ${TERRAIN_META[site.hex.terrain].label}, ${site.sector.designation}. ` +
        `Capture runs ${fmtDuration(MAP.captureMs)} and the landing is broadcast to everyone watching this sector.` +
        `${shutdown} There is no recall.`,
      confirmLabel: 'LAUNCH',
      cancelLabel: 'HOLD',
      danger: site.risk.risk !== 'stable',
    });
    if (!agreed) return;

    // Re-validate: the world moved while the dialog was up.
    const fresh = stateOrNull();
    if (!fresh) {
      toast({ title: 'UPLINK LOST', body: 'No world snapshot. Stand by.', kind: 'bad' });
      return;
    }
    const recheck = legality(fresh, hexId);
    if (!recheck.ok) {
      toast({ title: 'SITE LOST', body: recheck.reason, kind: 'bad' });
      cardSig = '';
      renderCard(fresh);
      haptic([22, 40, 22]);
      return;
    }

    launching = true;
    launchBtn.disabled = true;
    scanBtn.disabled = true;
    haptic([22, 40, 22, 40, 110]);
    emitFx({ type: 'shake' });
    scene?.shake(FX.shakeBig);
    scene?.pulse(hexId, PALETTE.gold);
    playArming(hexId);

    const settleAt = performance.now() + CONSOLE.armMs;
    const res = await backend.deploy(hexId);
    const wait = Math.max(0, settleAt - performance.now());
    if (wait > 0) await new Promise<void>((r) => window.setTimeout(r, wait));

    if (!res.ok) {
      launching = false;
      launchBtn.disabled = false;
      scanBtn.disabled = false;
      stopArming();
      cardSig = '';
      const after = stateOrNull();
      if (after) renderCard(after);
      toast({ title: 'DROP REFUSED', body: res.error, kind: 'bad' });
      haptic([30, 60, 30]);
      return;
    }

    // Success: the shell reroutes to the map on the next state push. Do not
    // force a screen change — racing the router only produces a double wipe.
    scene?.pulse(hexId, PALETTE.teal);
    emitFx({
      type: 'capture',
      payload: {
        title: 'BOOTS ON THE GROUND',
        body: `Pod down at ${hexId}. Capture running — hold it.`,
      },
    });
  }

  // ── sync ──────────────────────────────────────────────────────────────────
  function syncAll(): void {
    const state = stateOrNull();
    if (!state) {
      renderStandby();
      return;
    }
    clock.sync(state.now);
    root.classList.remove('is-standby');

    scene?.sync(state, view.get());

    renderRotation(state);
    renderBanner(state);
    renderMode(state);
    buildManifest();
    renderSectorRail(state);

    // A target can evaporate under you: sector rotation, a rival landing, a
    // capture starting. Re-render rather than pretending the dossier is fresh.
    if (targetHexId && !state.world.hexes[targetHexId]) targetHexId = undefined;
    renderSiteRail(state);
    renderCard(state);

    if (guildOpen) guildView?.sync(state);
  }

  function renderStandby(): void {
    if (root.classList.contains('is-standby')) return;
    root.classList.add('is-standby');
    cardSig = '';
    stopAll(cardTimers);
    clear(cardSlot);
    cardSlot.classList.add('is-void');
    cardSlot.appendChild(emptyState('◌', 'awaiting world snapshot — the console is listening'));
    launchBtn.disabled = true;
    prevBtn.disabled = true;
    nextBtn.disabled = true;
    cycleCount.textContent = '—';
  }

  // ── lifecycle ─────────────────────────────────────────────────────────────
  window.addEventListener('pagehide', () => {
    teardownScene();
  });

  renderStandby();

  return {
    el: root,

    mount(): void {
      if (mounted) return;
      mounted = true;
      launching = false;
      acquireAcc = 0;
      flightUntil = performance.now() + CONSOLE.flightMs;
      buildScene();
      scene?.resize();

      disposer.add(game.subscribe(() => syncAll()));
      disposer.add(view.subscribe(() => syncAll()));
      disposer.listen(window, 'resize', () => scene?.resize());

      syncAll();

      // Open on a recommendation rather than on empty space.
      const state = stateOrNull();
      if (state && offers.length === 0) runScan(false);
      if (state && targetHexId === undefined && offers.length > 0) {
        selectSite(offers[0], { focus: true, pulse: true });
      }

      openBrief(false);
    },

    unmount(): void {
      if (!mounted) return;
      mounted = false;
      disposer.dispose();
      stopAll(cardTimers);
      stopAll(rotTimers);
      closeBrief();
      closeGuild();
      stopArming();
      launching = false;
      launchBtn.disabled = false;
      scanBtn.disabled = false;
      cardSig = '';
      rotSig = '';
      bannerSig = '';
      siteRailSig = '';
      sectorRailSig = '';
      // One-way door: the map screen builds its own context the moment this
      // returns, so the staging context has to be gone before it does.
      teardownScene();
    },

    frame(dt: number): void {
      if (!mounted || launching || !scene) return;
      acquireAcc += dt;
      if (acquireAcc < CONSOLE.acquireMs) return;
      acquireAcc = 0;
      if (performance.now() < flightUntil) return;
      if (guildOpen || briefLayer.classList.contains('is-open')) return;

      const rect = aim.getBoundingClientRect();
      const hit = scene.hexAtScreen(rect.left + rect.width / 2, rect.top + rect.height / 2);
      if (!hit || hit === targetHexId) return;
      selectSite(hit);
    },
  };
}
